*{box-sizing:border-box} :root{--ink:#101619;--muted:#839093;--line:rgba(224,237,232,.13);--acid:#c5f06c;--white:#edf2ed}html,body,#game{margin:0;width:100%;height:100%;overflow:hidden;background:#151c1d;color:var(--white);font-family:Manrope,Arial,sans-serif}body{user-select:none}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,13,14,.68),transparent 30%,transparent 70%,rgba(8,13,14,.28)),linear-gradient(0deg,rgba(8,13,14,.58),transparent 34%,rgba(8,13,14,.25))}.grain{position:absolute;inset:0;pointer-events:none;opacity:.08;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.34'/%3E%3C/svg%3E");mix-blend-mode:overlay}.topbar{height:74px;position:absolute;left:0;right:0;top:0;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(11,17,18,.74),rgba(11,17,18,.16));z-index:3}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:37px;height:37px;border:1px solid rgba(197,240,108,.8);color:var(--acid);display:grid;place-items:center;font:800 21px 'Barlow Condensed';letter-spacing:-2px;transform:skew(-7deg)}.brand-mark span{color:white}.brand-title{font:800 17px 'Barlow Condensed';letter-spacing:1.6px}.brand-title b{color:var(--acid)}.brand-sub{font:9px 'DM Mono';letter-spacing:1.1px;color:#8f9b99;margin-top:3px}.top-center{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:10px 'DM Mono';letter-spacing:.8px;color:#c3ceca}.top-center i{height:13px;width:1px;background:#54605e;margin:0 4px}.live-dot{height:6px;width:6px;background:var(--acid);border-radius:50%;box-shadow:0 0 10px var(--acid)}.top-right{display:flex;align-items:center;gap:20px}.wallet{font:500 13px 'DM Mono';color:#e8eee8}.wallet-icon{color:var(--acid);margin-right:7px}.icon-btn,.close-modal,.map-overlay-head button{border:1px solid var(--line);background:rgba(255,255,255,.04);color:#eaf0e9;width:35px;height:35px;font-size:19px;cursor:pointer}.left-rail{position:absolute;z-index:2;left:36px;top:105px;width:227px}.profile{display:flex;align-items:center;position:relative;gap:10px;height:48px;margin-bottom:32px}.avatar{height:35px;width:35px;background:#a6c85b;color:#152019;display:grid;place-items:center;font:800 20px 'Barlow Condensed';clip-path:polygon(15% 0,100% 0,100% 82%,84% 100%,0 100%,0 17%)}.profile b{font:700 11px 'DM Mono';letter-spacing:1px;display:block}.profile small{font:9px 'DM Mono';color:#8e9b97;display:block;margin-top:4px}.profile em{color:var(--acid);font-style:normal}.rank-progress{position:absolute;bottom:0;left:46px;right:0;height:2px;background:#414b49}.rank-progress span{display:block;width:34%;height:100%;background:var(--acid)}.rail-label{font:9px 'DM Mono';letter-spacing:1.6px;color:#aab5b0}.vehicle-name{font:800 32px/.96 'Barlow Condensed';letter-spacing:.7px;margin-top:7px}.vehicle-meta{font:9px 'DM Mono';letter-spacing:.5px;color:#a4afaa;margin:8px 0 17px}.stat-row{height:28px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);font:9px 'DM Mono';letter-spacing:.8px;color:#929f9a}.stat-row b{font:11px 'DM Mono';color:#f0f3ed}.stat-row b small{font-size:8px;color:#adb8b1}.rail-divider{border-top:1px solid var(--line);margin:14px 0 17px}.session-item{display:flex;align-items:center;gap:9px;margin:12px 0 25px}.session-icon{color:var(--acid);font-size:17px}.session-item b,.session-item small{display:block}.session-item b{font:10px 'DM Mono';letter-spacing:.6px}.session-item small{font:8px 'DM Mono';color:#8e9b97;margin-top:4px}.chevron{color:#8e9b97;margin-left:auto;font-size:19px}.event-card{height:126px;width:100%;position:relative;overflow:hidden;text-align:left;border:1px solid rgba(196,238,108,.28);background:linear-gradient(125deg,rgba(29,48,42,.95),rgba(20,30,31,.84));color:var(--white);padding:13px 15px;cursor:pointer}.event-card:before{content:'';position:absolute;right:-16px;bottom:-38px;width:130px;height:110px;border:1px solid rgba(197,240,108,.25);transform:rotate(-25deg);box-shadow:0 0 0 12px rgba(197,240,108,.035),0 0 0 25px rgba(197,240,108,.03)}.event-kicker{display:block;font:8px 'DM Mono';letter-spacing:1.5px;color:var(--acid);margin-bottom:7px}.event-card b{font:700 20px/.9 'Barlow Condensed';letter-spacing:.9px}.event-foot{position:absolute;bottom:12px;left:15px;right:15px;border-top:1px solid rgba(255,255,255,.13);padding-top:7px;font:8px 'DM Mono';color:#b0bbb5}.event-foot i{float:right;color:var(--acid);font-style:normal;font-size:14px}.event-glow{position:absolute;right:24px;bottom:18px;width:28px;height:28px;border:1px solid rgba(197,240,108,.4);border-radius:50%;box-shadow:0 0 18px rgba(197,240,108,.14)}.left-bottom{display:flex;align-items:center;gap:6px;margin-top:23px;font:7px 'DM Mono';color:#8c9893;letter-spacing:.3px;white-space:nowrap}.keycap{display:inline-grid;place-items:center;min-width:17px;height:17px;border:1px solid rgba(240,245,240,.3);color:#e3e9e3;font:8px 'DM Mono';padding:0 4px}.keycap.space{margin-left:7px;min-width:43px}.right-stack{position:absolute;right:34px;top:99px;width:204px;z-index:2}.map-card{border:1px solid rgba(222,239,231,.18);background:rgba(13,20,20,.78);padding:11px 11px 9px;backdrop-filter:blur(8px)}.map-head,.map-footer{display:flex;justify-content:space-between;align-items:center;font:8px 'DM Mono';letter-spacing:1px;color:#d9e1da}.map-live{font-size:7px;color:var(--acid)}#minimap{width:180px;height:180px;display:block;margin:8px auto 5px;background:#1a2828}.map-footer{font-size:7px;color:#8e9c96;letter-spacing:.3px}.map-footer b{color:#d8e0db;font-weight:400}.objective{margin-top:11px;border-left:2px solid var(--acid);background:rgba(15,22,22,.73);padding:10px 12px;backdrop-filter:blur(5px)}.objective-top,.objective-bottom{display:flex;justify-content:space-between;font:7px 'DM Mono';letter-spacing:.8px;color:#9eaaa5}.objective-distance{color:var(--acid)}.objective b{display:block;font:700 20px/.9 'Barlow Condensed';letter-spacing:.4px;margin:8px 0}.objective-bottom{border-top:1px solid var(--line);padding-top:8px;color:#b1bdb5}.objective-bottom span:last-child{color:var(--acid);font-size:13px}.speed-panel{position:absolute;bottom:35px;right:35px;width:293px;height:138px;background:rgba(13,20,20,.83);border:1px solid rgba(222,239,231,.17);padding:13px 15px 11px;display:grid;grid-template-columns:41px 95px 1fr;grid-template-rows:77px 1fr;column-gap:9px;z-index:2;backdrop-filter:blur(8px)}.speed-left{border-right:1px solid var(--line);position:relative}.gear-label,.speed-unit{font:7px 'DM Mono';letter-spacing:1px;color:#87948e}.gear{font:800 35px/.95 'Barlow Condensed';color:var(--acid);margin-top:3px}.drive-pill{position:absolute;bottom:7px;left:0;font:7px 'DM Mono';color:#aab6af;border:1px solid #49554e;padding:3px 4px}.drive-pill span{color:var(--acid);font-size:6px}.speed-main{position:relative;border-right:1px solid var(--line)}.speed-number{font:800 53px/.9 'Barlow Condensed';letter-spacing:1px}.speed-unit{margin-top:7px}.rpm-box{padding:1px 0 0 3px}.rpm-header{display:flex;justify-content:space-between;font:7px 'DM Mono';color:#95a19a;letter-spacing:.7px}.rpm-header b{color:var(--acid);font-weight:400}.rpm-bars{height:47px;display:flex;gap:2px;align-items:flex-end;margin-top:7px}.rpm-bars i{display:block;flex:1;background:#657165;height:var(--h);opacity:.84}.rpm-bars i.on{background:var(--acid)}.rpm-bars i.red{background:#f17957}.speed-bottom{grid-column:1/4;display:flex;align-items:end;gap:12px;border-top:1px solid var(--line);padding-top:8px}.condition{flex:1;display:grid;grid-template-columns:47px 1fr;align-items:center;gap:5px;font:7px 'DM Mono';color:#9ba8a1}.condition div{height:3px;background:#3b4742}.condition i{height:100%;display:block;background:var(--acid)}.drift-score{position:absolute;bottom:72px;left:50%;transform:translateX(-50%);text-align:center;z-index:2;opacity:0;transition:opacity .25s;text-shadow:0 2px 8px #000}.drift-score.active{opacity:1}.score-label{font:9px 'DM Mono';letter-spacing:2px;color:#e3e9de}.score-dot{display:inline-block;width:6px;height:6px;background:var(--acid);border-radius:50%;margin:0 7px 1px 0;box-shadow:0 0 10px var(--acid)}.score-value{font:800 43px/.96 'Barlow Condensed';color:var(--acid);text-shadow:0 0 22px rgba(197,240,108,.35)}.score-combo{font:8px 'DM Mono';letter-spacing:1.4px;color:#d1dbd1}.toast{position:absolute;left:50%;top:92px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;padding:12px 16px;background:rgba(14,22,21,.85);border:1px solid rgba(197,240,108,.33);z-index:4;transition:opacity .4s}.toast>span{font-size:20px;color:var(--acid)}.toast b,.toast small{display:block}.toast b{font:700 10px 'DM Mono';letter-spacing:1px}.toast small{font:8px 'DM Mono';color:#a1ada7;margin-top:5px}.toast button{background:none;border:0;color:#9aa59f;font-size:18px;cursor:pointer;margin-left:10px}.toast.hidden{opacity:0;pointer-events:none}.controls-hint{position:absolute;bottom:43px;left:50%;transform:translateX(-50%);display:flex;gap:4px;align-items:center;z-index:2;white-space:nowrap}.controls-hint small{font:7px 'DM Mono';letter-spacing:.4px;color:#b4c0b9;margin-left:4px}.garage-trigger{position:absolute;right:35px;bottom:190px;background:rgba(16,24,22,.85);border:1px solid rgba(197,240,108,.45);color:var(--acid);padding:9px 13px;font:9px 'DM Mono';letter-spacing:1px;z-index:3;cursor:pointer}.garage-trigger>span{font-size:14px;vertical-align:-1px;margin-right:5px}.garage-trigger small{margin-left:14px;border:1px solid #66715e;padding:2px 4px;color:white;font-size:8px}.modal-backdrop,.map-overlay{display:none;position:absolute;inset:0;background:rgba(5,9,10,.78);backdrop-filter:blur(8px);z-index:8;align-items:center;justify-content:center}.modal-backdrop.open,.map-overlay.open{display:flex}.garage-modal{width:min(800px,calc(100vw - 32px));max-height:calc(100vh - 45px);background:#121a19;border:1px solid rgba(220,237,226,.2);box-shadow:0 30px 100px #000;padding:25px 31px;display:flex;flex-direction:column}.modal-header{display:flex;justify-content:space-between;align-items:flex-start}.modal-eyebrow{font:8px 'DM Mono';letter-spacing:1.8px;color:var(--acid)}.modal-header h1{font:800 34px 'Barlow Condensed';letter-spacing:1px;margin:5px 0 18px}.modal-header h1 i{font-style:normal;color:var(--acid)}.close-modal{font-size:24px}.garage-tabs{display:flex;border-bottom:1px solid var(--line);gap:26px}.garage-tabs button{border:0;background:none;color:#84918a;font:9px 'DM Mono';letter-spacing:1px;padding:12px 0;cursor:pointer;border-bottom:2px solid transparent}.garage-tabs button.active{color:var(--acid);border-bottom-color:var(--acid)}.garage-content{padding:20px 0;min-height:260px;overflow:auto}.car-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.car-card{position:relative;text-align:left;border:1px solid var(--line);background:#182220;color:var(--white);padding:12px;min-height:150px;cursor:pointer;overflow:hidden}.car-card.selected{border-color:var(--acid);background:linear-gradient(145deg,#293a2b,#19221f)}.car-swatch{height:54px;margin:-12px -12px 11px;background:linear-gradient(130deg,var(--car),#18201d 70%);position:relative}.car-swatch:after{content:'';position:absolute;left:20%;bottom:10px;width:60%;height:17px;border-radius:8px 13px 5px 5px;background:var(--car);border:1px solid rgba(255,255,255,.36);box-shadow:0 9px 0 -5px #090e0f,0 14px 0 -7px #cbd4c8}.car-card b{display:block;font:700 17px 'Barlow Condensed'}.car-card span{font:8px 'DM Mono';color:#9aa69f;display:block;margin-top:3px}.car-card .price{position:absolute;right:9px;bottom:10px;color:var(--acid)}.tuning-layout{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tune-control{background:#1a2421;padding:13px 14px}.tune-control header{display:flex;justify-content:space-between;font:9px 'DM Mono';color:#cbd4cd}.tune-control header b{color:var(--acid);font-weight:400}.tune-control input{width:100%;accent-color:#c5f06c;margin:15px 0 0}.paint-grid{display:flex;gap:12px;flex-wrap:wrap;padding:16px 3px}.paint-chip{width:49px;height:49px;border:2px solid transparent;cursor:pointer;transform:skew(-5deg);box-shadow:0 4px 14px #0008}.paint-chip.selected{border-color:#fff;outline:1px solid var(--acid)}.paint-info{font:10px 'DM Mono';color:#9aa69f;width:100%;margin-top:12px}.modal-footer{border-top:1px solid var(--line);padding-top:14px;display:flex;align-items:center;justify-content:space-between;font:7px 'DM Mono';color:#8b9891;letter-spacing:.5px}.modal-footer button{background:var(--acid);border:0;padding:11px 14px;font:800 9px 'DM Mono';letter-spacing:.7px;color:#172019;cursor:pointer}.modal-footer button b{margin-left:15px}.map-overlay-card{width:min(800px,calc(100vw - 30px));background:#131c1b;border:1px solid rgba(220,237,226,.2);padding:22px;box-shadow:0 30px 90px #000}.map-overlay-head{display:flex;justify-content:space-between;align-items:center;font:700 17px 'Barlow Condensed';letter-spacing:1px}.map-overlay-head b{font:9px 'DM Mono';color:#97a39c}.map-overlay-head button{font-size:22px}.map-overlay-card canvas{display:block;width:min(100%,560px);height:auto;max-height:65vh;aspect-ratio:1;margin:13px auto;background:#1a2828}.map-legend{display:flex;align-items:center;gap:18px;font:8px 'DM Mono';color:#c5d0c8}.map-legend span:first-child{color:var(--acid)}.map-legend span:nth-child(2){color:#ff9b62}.map-legend small{margin-left:auto;color:#87938d}.mobile-controls{display:none}.event-card:hover,.garage-trigger:hover,.modal-footer button:hover{filter:brightness(1.13)}
@media(max-width:850px){.topbar{height:58px;padding:0 16px}.brand-sub{display:none}.top-center{display:none}.left-rail{left:16px;top:77px;width:185px}.profile{margin-bottom:20px}.right-stack{right:14px;top:75px;width:165px}.map-card{padding:8px}.map-card #minimap{width:145px;height:145px}.objective{display:none}.speed-panel{right:14px;bottom:14px;transform:scale(.88);transform-origin:bottom right}.garage-trigger{right:14px;bottom:148px}.controls-hint{display:none}.toast{top:68px;width:max-content;max-width:90vw}.drift-score{bottom:165px}.left-bottom{display:none}}
@media(max-width:600px){.left-rail{top:76px;width:150px}.profile{margin-bottom:13px}.left-rail .rail-label,.left-rail .stat-row,.rail-divider,.session-item,.event-card{display:none}.vehicle-name{font-size:27px}.vehicle-meta{font-size:8px;margin:5px 0}.right-stack{top:auto;bottom:150px;right:10px;width:122px}.map-card{padding:6px}.map-card #minimap{width:108px;height:108px;margin:5px auto}.map-footer{font-size:6px}.map-head{font-size:7px}.speed-panel{right:9px;bottom:8px;transform:scale(.75)}.garage-trigger{right:9px;bottom:117px;padding:7px 9px}.toast{top:64px;padding:9px;width:calc(100% - 24px)}.toast small{font-size:7px;line-height:1.4}.drift-score{bottom:150px}.mobile-controls{position:absolute;bottom:18px;left:14px;right:auto;display:grid;grid-template-columns:48px 48px;gap:7px;z-index:3}.mobile-controls button{height:46px;color:white;background:rgba(20,28,26,.76);border:1px solid #b5c3b34d;font:700 10px 'DM Mono';touch-action:none}.mobile-controls button[data-control=brake]{grid-column:1/3;color:var(--acid);font-size:8px}.mobile-controls button[data-control=gas]{display:none}.modal-backdrop{align-items:flex-end}.garage-modal{padding:17px 17px 13px;max-height:88vh;width:100%;border-bottom:0}.modal-header h1{font-size:28px;margin-bottom:10px}.garage-content{min-height:190px;padding:13px 0}.car-grid{grid-template-columns:repeat(2,1fr)}.car-card{min-height:126px}.car-swatch{height:42px}.modal-footer{gap:12px}.modal-footer span{max-width:130px;line-height:1.5}.modal-footer button{font-size:8px;padding:10px}.map-legend{gap:8px;flex-wrap:wrap}.map-legend small{width:100%;margin:0}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), sceneCanvas=$('#scene');
const renderer=new THREE.WebGLRenderer({canvas:sceneCanvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x536b72);scene.fog=new THREE.FogExp2(0x536b72,.00165);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,1800);
scene.add(new THREE.HemisphereLight(0xb7d4da,0x29302a,1.35));
const sun=new THREE.DirectionalLight(0xffd5a1,2.1);sun.position.set(-220,300,120);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-230;sun.shadow.camera.right=230;sun.shadow.camera.top=230;sun.shadow.camera.bottom=-230;scene.add(sun);
const world=new THREE.Group();scene.add(world);
const mats={road:new THREE.MeshStandardMaterial({color:0x303738,roughness:.92}),side:new THREE.MeshStandardMaterial({color:0x68706a,roughness:1}),line:new THREE.MeshBasicMaterial({color:0xb8b28e}),ground:new THREE.MeshStandardMaterial({color:0x505c52,roughness:1}),building:[],window:new THREE.MeshStandardMaterial({color:0x46565a,roughness:.6,emissive:0x18272a,emissiveIntensity:.42}),concrete:new THREE.MeshStandardMaterial({color:0x626963,roughness:.94}),grass:new THREE.MeshStandardMaterial({color:0x414f42,roughness:1})};
[0x646d6a,0x74746b,0x4c585a,0x77796f,0x526065,0x82796c,0x596568].forEach(c=>mats.building.push(new THREE.MeshStandardMaterial({color:c,roughness:.88})));
const boxGeo=new THREE.BoxGeometry(1,1,1);const plane=new THREE.Mesh(new THREE.PlaneGeometry(1500,1500),mats.ground);plane.rotation.x=-Math.PI/2;plane.position.y=-.12;plane.receiveShadow=true;world.add(plane);
function addBox(parent,x,y,z,w,h,d,mat,cast=false){const m=new THREE.Mesh(boxGeo,mat);m.position.set(x,y+h/2,z);m.scale.set(w,h,d);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function addRoad(x,z,w,d){addBox(world,x,-.035,z,w,.16,d,mats.road);}
// A broad, readable street grid with a diagonal freeway and a dry canal.
const cityRoads=[];for(let p=-480;p<=480;p+=100){addRoad(p,0,18,1020);addRoad(0,p,1020,18);cityRoads.push(p)}
// Freeway ribbon and dashed lane markers.
const highway=new THREE.Mesh(new THREE.BoxGeometry(1000,.22,29),new THREE.MeshStandardMaterial({color:0x242a2c,roughness:.8}));highway.position.set(0,.01,155);highway.receiveShadow=true;world.add(highway);
for(let x=-490;x<500;x+=16){addBox(world,x,.13,155,8,.018,.22,mats.line);}
// side shoulders
addBox(world,0,.03,138,1000,.08,1.2,mats.side);addBox(world,0,.03,172,1000,.08,1.2,mats.side);
// Urban blocks; keep streets and central starting boulevard clear.
let seed=918273;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
for(let gx=-4;gx<5;gx++)for(let gz=-4;gz<5;gz++){
 if(Math.abs(gx)<=1&&Math.abs(gz)<=1)continue;
 const cx=gx*100,cz=gz*100;
 // A small park block in the east; warehouses toward the port.
 if(gx===3&&gz===-1){addBox(world,cx,0,cz,68,.22,68,mats.grass);for(let n=0;n<12;n++){const x=cx+(rand()-.5)*58,z=cz+(rand()-.5)*58;addTree(x,z,.65+rand()*.45)}continue;}
 const count=3+Math.floor(rand()*4);
 for(let n=0;n<count;n++){let x=cx+(rand()-.5)*65,z=cz+(rand()-.5)*65,w=12+rand()*19,d=13+rand()*20,h=(gz>1?12:18)+rand()*(gz>1?25:75);if(Math.abs(x)<65&&Math.abs(z)<65)continue;
 const mat=mats.building[Math.floor(rand()*mats.building.length)];addBox(world,x,0,z,w,h,d,mat,true);
 // lit facade window bands
 if(h>30&&rand()>.35){for(let floor=4;floor<h-2;floor+=5){addBox(world,x, floor,z+d/2+.011,w*.72,.45,.025,mats.window);}}
 }
}
function addTree(x,z,s=1){const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18*s,.25*s,2.4*s,6),new THREE.MeshStandardMaterial({color:0x51483c}));trunk.position.set(x,1.2*s,z);world.add(trunk);const top=new THREE.Mesh(new THREE.IcosahedronGeometry(1.3*s,1),new THREE.MeshStandardMaterial({color:0x405644,roughness:1}));top.position.set(x,3*s,z);top.castShadow=true;world.add(top)}

// Distant hills frame the city and the northbound desert drive.
for(let i=0;i<36;i++){const a=i/36*Math.PI*2,r=550+rand()*120,h=65+rand()*120;const hill=new THREE.Mesh(new THREE.ConeGeometry(60+rand()*70,h,5),new THREE.MeshStandardMaterial({color:i%3===0?0x4d5a50:0x566459,roughness:1}));hill.position.set(Math.cos(a)*r,h/2-5,Math.sin(a)*r);hill.rotation.y=rand()*2;world.add(hill)}
// Street lamps along the main avenues.
const lampMat=new THREE.MeshStandardMaterial({color:0x343b38,metalness:.5,roughness:.5}),bulbMat=new THREE.MeshBasicMaterial({color:0xffd69a});
