5:  if(tab==='cars'){const grid=document.createElement('div');grid.className='car-grid';carDefs.forEach((d,i)=>{const card=document.createElement('button');card.className=`car-card ${i===currentCar?'selected':''}`;card.innerHTML=`<div class="car-swatch" style="--car:#${d.color.toString(16).padStart(6,'0')}"></div><b>${d.name}</b><span>${d.brand} · ${d.hp} PS · ${d.drive}</span><span class="price">${unlocked.has(i)?(i===currentCar?'AKTIV':'AUSWÄHLEN'):'＄ '+d.cost}</span>`;card.onclick=()=>{if(!unlocked.has(i)){const cost=Number(d.cost.replace('.',''));if(money<cost){toast('ZU WENIG GELD','FAHRE DRIFTS UND VERDIENE CASH.');return}money-=cost;unlocked.add(i);$('#money').textContent=money.toLocaleString('de-DE')}currentCar=i;paintColor=null;buildCar(d);updateCarUI();renderGarage('cars')};grid.appendChild(card)});content.appendChild(grid)}
