 if(activeTab==='cars'){root.innerHTML=`<div class="car-grid">${defs.map((d,i)=>{const price=i<3?0:Math.round(11500+i*4600),owned=unlocked.has(i);return `<button class="car-card ${i===current?'selected':''} ${owned?'':'locked'}" data-car="${i}"><span class="car-swatch" style="--swatch:#${d.color.toString(16).padStart(6,'0')}"><span>${owned?'◈':'🔒'}</span><small>${d.drive}</small></span><b>${d.name}</b><small>${d.brand} · ${d.hp} PS</small><em>${i===current?'AUSGEWÄHLT':owned?'FAHREN':`KAUFEN · $${price.toLocaleString('de-DE')}`}</em></button>`}).join('')}</div>`;
