  root.querySelectorAll('[data-tune]').forEach(input=>input.oninput=()=>{const v=+input.value;({turbo:v=>turbo=v,grip:v=>gripTune=v,steer:v=>steerTune=v,score:v=>scoreTune=v})[input.dataset.tune](v);garage();const focused=root.querySelector(`[data-tune="${input.dataset.tune}"]`);if(focused){focused.focus();focused.setSelectionRange?.(0,0)}updateCarUI()});$('#manualToggle').onclick=()=>{manual=!manual;garage()};
 }else{root.innerHTML=`<div class="paint-grid">${colors.map(([name,color])=>`<button class="paint-chip ${paintColor===color?'chosen':''}" data-color="${color}" style="--swatch:#${color.toString(16).padStart(6,'0')}"><i></i><span>${name}</span></button>`).join('')}</div><p class="paint-note">LACKIERUNG · KOSTENLOS · JEDERZEIT ÄNDERBAR</p>`;root.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{paintColor=+b.dataset.color;buildCar();garage()})}
}
