function openGarage(){garage();$('#modalBackdrop').classList.add('open');heldReset()}
function closeGarage(){$('#modalBackdrop').classList.remove('open')}
function heldReset(){for(const k of Object.keys(held))delete held[k];input()}
$('#garageBtn').onclick=openGarage;$('#closeModal').onclick=closeGarage;$('#backToDrive').onclick=closeGarage;
document.querySelectorAll('.garage-tabs button').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;garage()}));
$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeGarage()});
function openMap(){if($('#modalBackdrop').classList.contains('open'))return;$('#mapOverlay').classList.add('open');mapUpdate()}
