$('#dismissToast').onclick=()=>$('#toast').classList.remove('show');
$('#settingsBtn').onclick=()=>{weather=(weather+1)%3;const modes=['NACHTFAHRT','NEBEL','REGEN'];$('#weather').textContent=modes[weather];scene.fog.density=weather===1?.0028:weather===2?.0019:.0016;scene.background.set(weather===1?0x465b61:weather===2?0x3e5058:0x536b72);sun.intensity=weather===2?1.45:2.1;toast('WETTER UMgeschaltet',`${modes[weather]} · Fahre vorsichtig`)};
document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyT'||e.code==='Tab'){e.preventDefault();$('#modalBackdrop').classList.contains('open')?closeGarage():openGarage();return}if(e.code==='KeyM'){e.preventDefault();$('#mapOverlay').classList.contains('open')?closeMap():openMap();return}if(e.code==='Escape'){closeGarage();closeMap();return}if(e.code==='KeyE'&&manual)player.gear=Math.min(6,player.gear+1);if(e.code==='KeyQ'&&manual)player.gear=Math.max(1,player.gear-1);held[e.code]=true;input()});
document.addEventListener('keyup',e=>{held[e.code]=false;input()});
window.addEventListener('blur',heldReset);
document.querySelectorAll('.mobile-controls button').forEach(b=>{const key=`touch-${b.dataset.control}`;const down=e=>{e.preventDefault();held[key]=true;input()};const up=e=>{e.preventDefault();held[key]=false;input()};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
let last=performance.now(),mapClock=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-last)/1000);last=now;if(!$('#modalBackdrop').classList.contains('open'))drive(dt);else{car.position.set(player.x,.03,player.z);car.rotation.y=player.yaw}mapClock+=dt;if(mapClock>.12){mapUpdate();mapClock=0}renderer.render(scene,camera)}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);
updateCarUI();hud(0,0);drawMap($('#minimap'));toast('LOS SANTOS ERWARTET DICH','WASD / PFEILTASTEN ZUM FAHREN · LEERTASTE FÜR HANDBREMSE');requestAnimationFrame(frame);

